#!/usr/bin/env python3
"""Summarise the four AGRILENS-MULTICROP 1.0.0 training runs and apply the pre-declared selection rule (training/configurations/SELECTION_RULE.md).
Reads only training-run artefacts (validation metrics); no test tier is read.
  python report_runs.py --runs <training_runs/agrilens-multicrop-1.0.0> --out <repo>/training/reports/agrilens-multicrop-1.0.0
Expects each run to have been exported with export_onnx.py into <run>/onnx_export/ (for model size and ONNX parity)."""
import argparse, csv, json, os
RUNS = ["multicrop1_R1_s42", "multicrop1_R2_s42", "multicrop1_R1_s43", "multicrop1_R2_s43"]
ap = argparse.ArgumentParser(); ap.add_argument("--runs", required=True); ap.add_argument("--out", required=True); a = ap.parse_args(); os.makedirs(a.out, exist_ok=True)
J = lambda *p: json.load(open(os.path.join(*p), encoding="utf-8"))
out = {}
for r in RUNS:
    d = os.path.join(a.runs, r); s = J(d, "summary.json"); vm = J(d, "val_metrics.json"); info = J(d, "run_info.json")
    ep = list(csv.DictReader(open(os.path.join(d, "epochs.csv"), encoding="utf-8"))); best = [e for e in ep if int(e["epoch"]) == s["best_epoch"]][0]
    man = J(d, "onnx_export", "MODEL_MANIFEST.json")
    out[r] = {"recipe": s["recipe"], "seed": s["seed"], "architecture": info["config"]["model"], "trainable_params": s["trainable_params"],
              "dataset": "AGL-MULTICROP-MD 1.0.0", "split_files_sha256": {k: v for k, v in info["frozen_dataset_files_sha256"].items() if k.startswith("splits/train") or k.startswith("splits/val")},
              "epochs_run": s["epochs_run"], "best_epoch": s["best_epoch"], "train_minutes": round(s["train_minutes"], 1), "mean_epoch_seconds": round(s["mean_epoch_seconds"], 1), "hardware": s["hardware"],
              "train_loss_at_best": float(best["train_loss"]), "train_acc_augmented_at_best": float(best["train_acc_augmented"]),
              "val_loss": vm["loss"], "val_accuracy": vm["accuracy"], "val_macro_f1": vm["macro_f1"], "val_accuracy_by_crop": vm["by_crop"],
              "per_class": [{"class": c, **pc} for c, pc in zip(info["classes"], vm["per_class"])], "confusion_matrix": vm["confusion_matrix"],
              "onnx": {"sha256": man["sha256"], "bytes": man["bytes"], "parity": man["parity_vs_pytorch_256_validation_images"], "checkpoint_sha256": man["checkpoint_sha256"]}}
mean = {rc: sum(out[r]["val_macro_f1"] for r in RUNS if out[r]["recipe"] == rc) / 2 for rc in ("R1_last_stage", "R2_last_two_stages")}
diff = mean["R2_last_two_stages"] - mean["R1_last_stage"]
recipe = "R2_last_two_stages" if diff >= 0.005 else "R1_last_stage"
cands = [r for r in RUNS if out[r]["recipe"] == recipe]; chosen = max(cands, key=lambda r: out[r]["val_macro_f1"])
sel = {"rule": "training/configurations/SELECTION_RULE.md points 3-4 (validation only)", "mean_val_macro_f1_by_recipe": mean, "R2_minus_R1": diff,
       "chosen_recipe": recipe, "reason": "R2 better by >= 0.005" if recipe.startswith("R2") else "difference below 0.005 (or R1 better): R1 chosen (fewer trainable parameters)",
       "chosen_run": chosen, "chosen_val_macro_f1": out[chosen]["val_macro_f1"], "chosen_checkpoint": os.path.join(a.runs, chosen, "best.pt"), "test_data_read": False}
json.dump(out, open(os.path.join(a.out, "TRAINING_RUNS.json"), "w"), indent=1); json.dump(sel, open(os.path.join(a.out, "SELECTION.json"), "w"), indent=1)
classes = [p["class"] for p in out[RUNS[0]]["per_class"]]
L = ["# AGRILENS-MULTICROP 1.0.0 experiment register", "", "Generated by `training/scripts/report_runs.py` from the run folders. Validation split only (`splits/val.csv`, 3,844 images, single centre view). No test tier was read.", "",
     "| Run | Recipe | Seed | Trainable params | Epochs run | Best epoch | Minutes (CPU) | Train loss @best | Val loss | Val accuracy | Val macro-F1 | ONNX bytes | ONNX max logit diff | ONNX argmax agreement |", "|" + "---|" * 14]
for r in RUNS:
    o = out[r]; L.append(f"| {r} | {o['recipe']} | {o['seed']} | {o['trainable_params']:,} | {o['epochs_run']} | {o['best_epoch']} | {o['train_minutes']} | {o['train_loss_at_best']:.4f} | {o['val_loss']:.4f} | {o['val_accuracy']:.4f} | {o['val_macro_f1']:.4f} | {o['onnx']['bytes']:,} | {o['onnx']['parity']['max_abs_logit_diff']:.2e} | {o['onnx']['parity']['argmax_agreement']:.3f} |")
L += ["", f"Selection: mean val macro-F1 R1 {mean['R1_last_stage']:.4f}, R2 {mean['R2_last_two_stages']:.4f} (R2 - R1 = {diff:+.4f}). {sel['reason']}. Chosen run: **{chosen}** (val macro-F1 {out[chosen]['val_macro_f1']:.4f}).", "",
      "## Validation accuracy by crop", "", "| Run | " + " | ".join(out[RUNS[0]]["val_accuracy_by_crop"].keys()) + " |", "|---|" + "---|" * len(out[RUNS[0]]["val_accuracy_by_crop"])]
for r in RUNS: L.append(f"| {r} | " + " | ".join(f"{v['macro_f1']:.4f}" if isinstance(v, dict) else f"{v:.4f}" for v in out[r]["val_accuracy_by_crop"].values()) + " |")
L += ["", "## Per-class validation precision / recall / F1", "", "| Class | n | " + " | ".join(f"{r} P / R / F1" for r in RUNS) + " |", "|---|---|" + "---|" * len(RUNS)]
for k, c in enumerate(classes):
    L.append(f"| {c} | {out[RUNS[0]]['per_class'][k]['support']} | " + " | ".join(f"{out[r]['per_class'][k]['precision']:.3f} / {out[r]['per_class'][k]['recall']:.3f} / {out[r]['per_class'][k]['f1']:.3f}" for r in RUNS) + " |")
for r in RUNS:
    L += ["", f"## Confusion matrix, {r} (rows true, columns predicted; class order as labels.txt)", "", "| true \\ pred | " + " | ".join(str(i) for i in range(len(classes))) + " |", "|---|" + "---|" * len(classes)]
    for k, row in enumerate(out[r]["confusion_matrix"]): L.append(f"| {k} {classes[k]} | " + " | ".join(str(x) if x else "." for x in row) + " |")
open(os.path.join(a.out, "EXPERIMENT_REGISTER.md"), "w", encoding="utf-8", newline="\n").write("\n".join(L) + "\n"); print(json.dumps(sel, indent=1))
